// The map's look and where it gets its data: styles generated by the VersaTiles style package over the
// map data bundled with the app (see utils/mapData.js).
import { addProtocol, setWorkerUrl } from 'maplibre-gl';
import workerUrl from 'maplibre-gl/dist/maplibre-gl-worker.mjs?worker&url';
import { osm, satellite, inlineSources } from '@versatiles/style';
import { getSetting, MAP_STYLES } from '../../utils/settings';
import { isInMapData, MAP_ATTRIBUTION } from '../../utils/mapData';

// Vite bundles the worker into its own file; MapLibre would otherwise look for it next to its own chunk
setWorkerUrl(workerUrl);
// (MapLibre runs one worker here - its default outside Safari. Measured on the Android emulator, a
// second one adds about 60 MB to the renderer and does not make the bundled tiles draw any sooner.)

// The folder sits next to the page: /Tartubus/map/ on the website, https://localhost/map/ in the Android app
const MAP_DATA = new URL('./map/', document.baseURI).href;

let mapIndex;
export const loadMapIndex = () => {
  mapIndex ||= fetch(`${MAP_DATA}index.json`).then(response => {
    if (!response.ok) throw new Error(`Map data index: HTTP ${response.status}`);
    return response.json();
  });
  // A failed load is tried again the next time the map opens
  mapIndex.catch(() => { mapIndex = null; });
  return mapIndex;
};

// Tiles and fonts are asked for as mapdata://tiles/{z}/{x}/{y}.pbf and mapdata://glyphs/{font}/{range}.pbf.
// Only files the index lists are fetched; for the rest MapLibre gets an error without a request:
// - a tile outside the detailed area: the tile counts as failed and MapLibre draws the coarser tile
//   above it instead. The status must not be 404: a vector tile answered with 404 counts as loaded
//   and empty, which hides the coarser tile and leaves the area blank.
// - a character range the fonts folder lacks: MapLibre draws those characters with a system font.
export const NOT_IN_MAP_DATA = 410;
addProtocol('mapdata', async ({ url }, abortController) => {
  const index = await loadMapIndex();
  const file = url.slice('mapdata://'.length);
  const response = isInMapData(index, file)
    ? await fetch(MAP_DATA + file, { signal: abortController.signal })
    : { ok: false, status: NOT_IN_MAP_DATA };
  if (!response.ok) throw Object.assign(new Error(`No ${file} in the map data`), { status: response.status });
  return { data: await response.arrayBuffer() };
});

export const currentMapStyle = () => {
  const saved = getSetting('mapStyle');
  return MAP_STYLES.includes(saved) ? saved : MAP_STYLES[0];
};

const localUrls = (index) => ({
  osm: {
    tilejson: '3.0.0',
    tiles: ['mapdata://tiles/{z}/{x}/{y}.pbf'],
    minzoom: index.minzoom,
    maxzoom: index.maxzoom,
    attribution: MAP_ATTRIBUTION,
  },
  glyphsPattern: 'mapdata://glyphs/{fontstack}/{range}.pbf',
  sprite: [{ id: 'base', url: `${MAP_DATA}sprites/base` }],
});

// - projection: the generated styles default to a globe; this is a flat city map without rotation or pitch.
// - language 'local': every label in the feature's own name (Estonian here), not a translation.
// - satellite is the one style that needs the network: its imagery comes from tiles.versatiles.org
//   (inlineSources fetches the imagery's tile list); the roads and labels over it are the local data.
export async function buildStyle(mapStyle, isDarkMode) {
  const urls = localUrls(await loadMapIndex());
  if (mapStyle === 'satellite') {
    return inlineSources(satellite({ urls: { ...urls, base: 'https://tiles.versatiles.org' }, projection: 'mercator' }));
  }
  return osm({ urls, projection: 'mercator', theme: isDarkMode ? `${mapStyle}-dark` : mapStyle, text: { language: 'local' } });
}

// The font of the app's own map texts (cluster counts): one the map data ships
export const MAP_FONT_BOLD = ['noto_sans_bold'];
export const MAP_FONT = ['noto_sans_regular'];
